import pytest

from your_module import matrix_transpose


@pytest.mark.parametrize(
    "matrix, expected",
    [
        ([[1, 2], [3, 4]], [[1, 3], [2, 4]]),
        ([[1, 2, 3], [4, 5, 6]], [[1, 4], [2, 5], [3, 6]]),
        ([[1, 2], [3, 4], [5, 6]], [[1, 3, 5], [2, 4, 6]]),
        ([["a", None], [True, 3.14]], [["a", True], [None, 3.14]]),
    ],
)
def test_matrix_transpose_happy_paths(matrix, expected):
    assert matrix_transpose(matrix) == expected


@pytest.mark.parametrize(
    "matrix, expected",
    [
        ([], []),
        ([[]], []),
        ([[], []], []),
        ([[1, 2, 3]], [[1], [2], [3]]),
        ([[1], [2], [3]], [[1, 2, 3]]),
    ],
)
def test_matrix_transpose_edge_cases(matrix, expected):
    assert matrix_transpose(matrix) == expected


def test_matrix_transpose_does_not_mutate_input():
    matrix = [[1, 2], [3, 4]]
    original = [row[:] for row in matrix]

    result = matrix_transpose(matrix)

    assert result == [[1, 3], [2, 4]]
    assert matrix == original


@pytest.mark.parametrize(
    "matrix, expected",
    [
        pytest.param([[1], [2, 3], [4, 5]], [[1, 2, 4]], id="later_rows_longer"),
        pytest.param([[], [1, 2, 3]], [], id="empty_first_row"),
    ],
)
def test_matrix_transpose_ragged_rows_with_extra_values_are_ignored(matrix, expected):
    # Documents current behavior: the function uses len(matrix[0]),
    # so extra values in later rows are ignored.
    assert matrix_transpose(matrix) == expected


@pytest.mark.parametrize(
    "matrix",
    [
        [[1, 2], [3]],
        [[1], []],
        [[1, 2, 3], [4, 5, 6], [7, 8]],
    ],
)
def test_matrix_transpose_ragged_rows_shorter_than_first_raise_index_error(matrix):
    with pytest.raises(IndexError):
        matrix_transpose(matrix)


@pytest.mark.parametrize(
    "matrix",
    [
        pytest.param([1, 2, 3], id="rows_are_scalars"),
        pytest.param([None], id="first_row_is_none"),
        pytest.param([[1], object()], id="later_row_not_subscriptable"),
    ],
)
def test_matrix_transpose_invalid_non_empty_inputs_raise_type_error(matrix):
    with pytest.raises(TypeError):
        matrix_transpose(matrix)
```

Note: the ragged-row tests document the function’s current behavior. Rows shorter than the first row raise `IndexError`, while rows longer than the first row have their extra values ignored.
